/******************************************
 multiply words
 flags:  CZSV--
 ******************************************/
static uint32_t MULTW(uint16_t dest, uint16_t value)
{
	uint32_t result = (int32_t)(int16_t)dest * (int16_t)value;
	CLR_CZSV;
	CHK_XXXL_ZS;
	if(!value)
	{
		/* multiplication with zero is faster */
		Z->icount += (70-18);
	}
	if((int32_t)result < -0x8000 || (int32_t)result >= 0x8000) SET_C;
	return result;
}

/******************************************
 multiply longs
 flags:  CZSV--
 ******************************************/
static uint64_t MULTL(uint32_t dest, uint32_t value)
{
	uint64_t result = (int64_t)(int32_t)dest * (int32_t)value;
	if(!value)
	{
		/* multiplication with zero is faster */
		Z->icount += (282 - 30);
	}
	else
	{
		int n;
		for(n = 0; n < 32; n++)
			if(dest & (1L << n)) Z->icount -= 7;
	}
	CLR_CZSV;
	CHK_XXXQ_ZS;
	/* carry marks a product that will not fit in the low long: the
	   representable range is [-2^31, 2^31), so exactly -2^31 and
	   2^31-1 do fit */
	if((int64_t)result < -0x80000000LL || (int64_t)result >= 0x80000000LL) SET_C;
	return result;
}

/******************************************
 divide long by word
 flags: CZSV--
 ******************************************/
static uint32_t DIVW(uint32_t dest, uint16_t value)
{
	uint32_t result = dest;
	uint16_t remainder = 0;
	CLR_CZSV;
	if (value)
	{
		uint16_t qsign = ((dest >> 16) ^ value) & S16;
		uint16_t rsign = (dest >> 16) & S16;
		if ((int32_t)dest < 0) dest = -dest;
		if ((int16_t)value < 0) value = -value;
		result = dest / value;
		remainder = dest % value;
		if (qsign) result = -result;
		if (rsign) remainder = -remainder;
		if ((int32_t)result < -0x8000 || (int32_t)result > 0x7fff)
		{
			int32_t temp = (int32_t)result >> 1;
			SET_V;
			if (temp >= -0x8000 && temp <= 0x7fff)
			{
				/* CASE 4: the quotient is a 17-bit two's complement
				   number; the destination register keeps the low 16
				   bits and the S flag holds the sign-extension MSB, so
				   preserve the computed result rather than forcing -1/0.
				   S is that 17th bit - the sign of the whole quotient -
				   not bit 15 of the truncated remnant. */
				if ((int32_t)result < 0) SET_S;
				SET_C;
			}
		}
		else
		{
			CHK_XXXW_ZS;
		}
		result = ((uint32_t)remainder << 16) | (result & 0xffff);
	}
	else
	{
		SET_Z;
		SET_V;
	}
	return result;
}

